<script lang="ts">import type { Snippet } from 'svelte'; import { cn } from '../../utils.js'; import { useSandboxTabsContext } from './context.svelte.js'; let { value, class: className = '', children, ...rest }: { value: string; class?: string; children?: Snippet; [key: string]: unknown } = $props(); const context = useSandboxTabsContext(); const active = $derived(context.value === value);</script>
{#if active}<div {...rest} id={context.panelId(value)} role="tabpanel" aria-labelledby={context.tabId(value)} tabindex="0" data-state="active" data-value={value} class={cn('mt-0 text-sm', className)}>{@render children?.()}</div>{/if}
